     9	import type { ModelRegistry } from "@earendil-works/pi-coding-agent";
    10	import { Data } from "effect";
    11	
    12	export const BACKEND_NAMES = ["pi"] as const;
    13	export type BackendName = (typeof BACKEND_NAMES)[number];
    14	
    15	/** Who initiated the session. User asides stay out of model-facing tooling. */
    16	export type SubagentOrigin = "model" | "btw";
    17	
    18	/**
    19	 * Reasoning-effort scale; these are pi's thinking levels, used directly as the
    20	 * level. Omitted = inherit the parent session's level.
    21	 */
    22	export const REASONING_EFFORTS = [
    23	  "off",
    24	  "minimal",
    25	  "low",
    26	  "medium",
    27	  "high",
    28	  "xhigh",
    29	  "max",
    30	] as const;
    31	export type ReasoningEffort = (typeof REASONING_EFFORTS)[number];
    32	
    33	export type SubagentStatus = "running" | "done" | "error";
    34	export type SubagentOutcome = "completed" | "failed" | "interrupted";
    35	
    36	/** Parent-session context resolved by the tool layer and passed opaquely. */
    37	export interface ParentContext {
    38	  readonly parentCwd: string;
    39	  readonly sessionId?: string;
    40	  readonly originEntryId?: string | null;
    41	  readonly projectTrusted: boolean;
    42	  /** Parent pi model, for the pi backend's "inherit" default. */
    43	  readonly inheritedModel?: { readonly provider: string; readonly id: string };
    44	  readonly inheritedThinkingLevel?: string;
    45	  /** Parent model registry; required by the pi backend to resolve models. */
    46	  readonly modelRegistry?: ModelRegistry;
    47	}
    48	
    49	export interface SpawnTask {
    50	  /** Omitted for normal tool-driven spawns. */
    51	  readonly origin?: SubagentOrigin;
    52	  readonly prompt: string;
    53	  readonly title: string;
    54	  readonly cwd: string;
    55	  /**
    56	   * Model hint: "provider/model-id", or a bare model id resolved against the
    57	   * parent's provider. Omitted = inherit the parent model.
    58	   */
    59	  readonly model?: string;
    60	  /** Thinking level for the child; omitted inherits the parent level. */
    61	  readonly reasoningEffort?: ReasoningEffort;
    62	  /**
    63	   * Agent-type fields, resolved by the tool layer. The backend applies them
    64	   * verbatim; it does not know where they came from.
    65	   */
    66	  readonly appendSystemPrompt?: readonly string[];
    67	  /**
    68	   * Tool allowlist for the child. Composed with (never replacing) the child
