 26	function sliceStartToUtf8Bytes(content: string, maxBytes: number) {
 27	  const bytes = Buffer.from(content, "utf8");
 28	  if (bytes.length <= maxBytes) return content;
 29	  let end = maxBytes;
 30	  while (end > 0 && (bytes[end] & 0xc0) === 0x80) end--;
 31	  return bytes.subarray(0, end).toString("utf8");
 32	}
