 34	function ensureDirectory(parent: string, name: string) {
 35	  const directory = path.join(parent, name);
 36	  try {
 37	    mkdirSync(directory, { mode: 0o700 });
 38	  } catch (error) {
 39	    if ((error as NodeJS.ErrnoException).code !== "EEXIST") throw error;
 40	  }
 41	  const stat = lstatSync(directory);
 42	  if (!stat.isDirectory() || stat.isSymbolicLink()) {
 43	    throw new Error(`Unsafe result artifact directory: ${directory}`);
 44	  }
 45	  return directory;
 46	}
